<script type="text/template" name="createTranslationDialog">
<div class='dialog'>
   <ul class='fieldList'>
      <li>
         <label>[resource_displayname[culture]]</label>
         <div class='value'>
            <select name='culture'></select>
         </div>
      </li>
      <li>
     	<label>[resource_shortdisplayname[displayname]]</label>
        <div class="value">
        	<input type="text" name="displayName"></input>
        </div>
     </li>
     <li>
     	<label>[resource_shortdisplayname[shortdisplayname]]</label>
        <div class="value">
        	<input type="text" name="shortDisplayName"></input>
        </div>
     </li>
     <li>
     	<label>[resource_shortdisplayname[description]]</label>
        <div class="value">
