rs summary{padding:12px 16px;cursor:pointer;font-weight:700}.dt-response-headers pre{margin:0;padding:0 16px 16px;white-space:pre-wrap}.dt-hidden{display:none!important}
@media(max-width:900px){.dt-workspace{grid-template-columns:1fr}.dt-request-bar{grid-template-columns:110px 1fr}.dt-send{grid-column:1/-1;height:44px}.devtools-api{padding:14px}}@media(max-width:560px){.dt-request-bar{grid-template-columns:1fr}.dt-send{grid-column:auto}.dt-header-row{grid-template-columns:1fr auto}.dt-header-row input:nth-child(2){grid-column:1/2}.dt-header-row .dt-icon-button{grid-column:2;grid-row:1/3;height:100%}}
